cd /workspace && python3 -c "
import subprocess,os
print('pgid',os.getpgid(0),'pid',os.getpid(),'sid',os.getsid(0))
try:
    p=subprocess.Popen(['/bin/cat'],start_new_session=True,stdin=subprocess.PIPE,stdout=subprocess.PIPE); print('session ok',p.pid); p.kill(); p.wait()
except Exception as e: print('session fail',e)
try:
    p=subprocess.Popen(['/bin/cat'],preexec_fn=lambda: None); print('preexec ok'); p.kill(); p.wait()
except Exception as e: print('preexec fail',e)
"
